(1, '12', '', 'BIOS singkatan dariâ€¦.', NULL, 'Basic Internal Output Service', 'Basic Input Output System', 'Basic Input Output Service', 'Basic Internal Output System', 'Basic Instinc Output System', 'B', '4', '223', 'Y', NULL, '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
(2, '12', '', 'Jika menginstal sistem operasi melalui CD, maka diperlukanâ€¦.', NULL, 'Disket', 'CD Bootable', 'Harddisk', 'Micro SD', 'CD-R / DVD=R', 'B', '4', '223', 'Y', NULL, '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
(3, '12', '', 'File Sistem operasi windows ketika instalasi sebaiknya disimpan di direktoriâ€¦.', NULL, 'Local disk E', 'Local disk D', 'Local disk C', 'Local disk B', 'Local disk A', 'C', '4', '223', 'Y', NULL, '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
(4, '12', '', 'Di bawah ini yang termasuk Operating System berbasis GUI, Kecualiâ€¦.', NULL, 'Linux', 'Windows', 'Mac Os', 'DOS', 'Android', 'D', '4', '223', 'Y', NULL, '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
(5, '12', '', 'Yang tidak termasuk generasi dari varian Microsoft Windows adalahâ€¦.', NULL, 'Windows 98', 'Windows ME/2000', 'Windows Xp', 'Windows 2004', 'Windows 7', 'D', '4', '223', 'Y', NULL, '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
(6, '12', '', 'Yang dimaksud dengan proses â€œinstallasiâ€ adalahâ€¦.', NULL, 'Memindah data dari media penyimpan ke komputer', 'Perintah-perintah untuk menjalankan suatu proses', 'Membuat program dari yang belum ada menjadi ada', 'Menguraikan file-file & Menyesuaikan program dengan alat-alat yg terpasang pada komputer', 'Menyalin file-file dari program yang bersangkutan ke media penyimpan dan menjalankan ', 'D', '4', '223', 'Y', NULL, '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
(7, '12', '', 'Untuk menginstal OS dengan menggunakan CD maka pengaturan First Boot di BIOS di set menjadiâ€¦.', NULL, 'Setting 1st boot sequence hardisk 0', 'Seting 2nd boot sequence CD room', 'Setting 2nd boot sequence hardisk 0', 'Seting 1st boot sequence DVD room', 'Setting 1st boot sequence USB Drive', 'D', '4', '223', 'Y', NULL, '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
(8, '12', '', 'Dibawah ini adalah yang dapat di setting dalam sistem bios, kecualiâ€¦.', NULL, 'Setting Waktu', 'Setting boot sequence', 'Setting srceensaver', 'Seting suhu temperatur', 'Seting VGA dan sound', 'C', '4', '223', 'Y', NULL, '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
(9, '12', '', 'Yang harus tersedia sebelum kita meng-install software aplikasi pengolah kata adalahâ€¦.', NULL, 'Software sistem operasi', 'Software presentasi', 'Software utilitas', 'Software grafis dan multimedia', 'Software pengolah angka', 'A', '4', '223', 'Y', NULL, '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
(10, '12', '', 'Secara umum, CPU terdiri dariâ€¦.', NULL, 'Control unit, ALU dan keyboard', 'Control unit, mouse, ALU dan memory storage', 'Control unit, Aritmetical Logical Unit dan Register', 'ROM dan RAM', 'CD-ROM, VGA dan NIC', 'C', '4', '223', 'Y', NULL, '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
(11, '12', '', 'Hardware yang merupakan unit penyimpan adalahâ€¦.', NULL, 'CPU', 'Harddisk', 'Printer', 'Floppy Drive', 'CD Room Drive', 'B', '4', '223', 'Y', NULL, '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
(12, '12', '', 'Yang termasuk dalam perangkat keras adalahâ€¦.', NULL, 'Operating System', 'Programming Language', 'DVD RW drive', 'Utility', 'Driver', 'C', '4', '223', 'Y', NULL, '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
(13, '12', '', 'Sistem operasi adalahâ€¦.', NULL, 'penghubung antara brainware, hardware dan software', 'penghubung antara user dan software', 'penghubung user dengan user', 'penghubung software dengan hardware', 'penghubung antara hardware dan brainware', 'A', '4', '223', 'Y', NULL, '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
(14, '12', '', 'Fungsi dari sistem operasi adalah', NULL, 'Mengatur perangkat lunak dengan perangkat keras komputer', 'Mengatur semua operasi dari seluruh perangkat keras komputer', 'Mengatur operasi perangkat lunak komputer', 'Mengatur penggunaan komputer', 'Mengatur perintah komputer', 'A', '4', '223', 'Y', NULL, '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
(15, '12', '', 'Dalam melakukan upaya pencegahan agar perangkat lunak dapat terlindungi hak ciptanya dari pembajakan, maka perusahaan pembuat perangkat lunak melengkapi produknya dengan kode tertentu yang biasa disebut â€¦.', NULL, 'Serial number', 'Code number', 'Dial number', 'Passing number', 'Certificate number', 'A', '4', '223', 'Y', NULL, '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
(16, '12', '', 'Dualboot dalam sistem operasi berartiâ€¦.', NULL, 'dapat dijalankan bersama system operasi yang lain', 'dapat dijalankan oleh lebih dari satu pengguna', 'dapat dijalankan di lebih dari satu komputer', 'dapat melakukan tugas secara bersamaan', 'memiliki lebih dari satu versi', 'C', '4', '223', 'Y', NULL, '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
(17, '12', '', 'Tombol Shut down pada sistem operasi berfungsi untukâ€¦.', NULL, 'Mematikan monitor', 'Membatalkan perintah terakhir', 'Merestart komputer', 'Menghidupkan komputer', 'Mematikan komputer', 'E', '4', '223', 'Y', NULL, '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
(18, '12', '', 'Ketika Setup selesai dijalankan, berarti proses instalasi sistem operasi telah selesai dan sudah bisa dioperasikan. Namun terkadang tampilannya masih kasar dan sound card belum berfungsi. Ketika Sound card, VGA card, printer, Network/internet CardÂ  penggunannya belum bisa optimal, maka perlu menginstal â€¦.', NULL, 'Aplikasi', 'Program', 'Driver', 'Anti virus', 'Norton Utility', 'C', '4', '223', 'Y', NULL, '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
(19, '12', '', 'Ketika anda bekerja dengan suatu program, tidak selamanya program tersebut bekerja dengan baik. Ada kalanya program tersebut tidak berfungsi sebagaimana mestinya, sehingga tidak dapat menerima perintah-perintah dari pemakai. Dalam keadaan ini dikatakan bahwa program itu telah membeku atau biasa kita sebut dengan istilahâ€¦.', NULL, 'Restart', 'Shoutdown', 'Standby', 'Hang', 'Low memory', 'D', '4', '223', 'Y', NULL, '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
(20, '12', '', 'Ketika anda bekerja dengan suatu program, tidak selamanya program tersebut bekerja dengan baik. Ada kalanya program tersebut tidak berfungsi sebagaimana mestinya, sehingga tidak dapat menerima perintah-perintah dari pemakai. Tetapi anda dapat mematikan program tersebut secara paksa dengan menekan tombol keyboard secara bersamaan, yaitu â€¦.', NULL, 'Alt+F4', 'Ctrl+P', 'Ctrl+I', 'Ctrl+Alt+Del', 'Tap+Alt+Del', 'D', '4', '223', 'Y', NULL, '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
(21, '12', '', 'Selama proses instalasi sistem operasi berlangsung, akan muncul beberapa jendela untuk konfigurasi. Pada bagian Regional and Language Options, kita akan memilih â€¦', NULL, 'Negara dan Bahasa', 'Waktu', 'Pasword', 'Jaringan', 'Serial Number', 'A', '4', '223', 'Y', NULL, '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
(22, '12', '', 'Secara normal, komputer menyimpan data pada hardisk secara continue. Akan tetapi, pada keadaan tertentu komputer menyimpan data tersebut secara terpecah-pecah. Dalam keadaan seperti ini, komputer akan membutuhkan waktu yang lebih lama untuk membaca data dari hardisk. Untuk menyatukan data yang terpecah-pecah menjadi data yang continue, menggunakan programâ€¦.', NULL, 'System Restore', 'Disk Cleanup', 'Character Map', 'System Backup', 'Disk Defragmenter', 'E', '4', '223', 'Y', NULL, '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
(23, '12', '', 'Menghapus program aplikasi adalah bagian yang sangat penting dalam Windows karena hal ini sangatlah sering kita gunakan. Cara untuk menghapus program aplikasi di Windows 7 adalahâ€¦.', NULL, 'Start Menu > Control Panel  > Printers and faxes > Pilih Program > Uninstall', 'Start Menu > Settting  > Control Panel  > Add/Remove Program > Pilih Program > Uninstall', 'Start Menu > Control Panel  > Network Connection > Pilih Program > Uninstall', 'Start Menu > Control Panel  > Add/Remove > Pilih Program > Unistall Program > Taskbar and Start menu > Pilih Program > Uninstall', 'Start Menu > Control Panel  > Programs > Programs and Features > Pilih Program > Uninstall', 'E', '4', '223', 'Y', NULL, '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
(24, '12', '', 'Screensaver adalah tampilan sesaat pada waktu komputer tidak digunakan dalam keadaan â€¦.', NULL, 'Rusak', 'Menyala', 'Hidup', 'Mati', 'Standby', 'B', '4', '223', 'Y', NULL, '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
