(48, '3', '', 'Manakah di antara kalimat berikut yang termasuk pernyataan deduktif?......', NULL, 'karena bangun kesiangan ia datang terlambat', 'disebabkan oleh penyakitnya,ia menghentikan kativitas di luar rumah', 'mengapa permasalahan itu diperumit jika semua sudah jelas ', 'jika hari hujan, ia tidak menghadiri rapat', 'seandainya mereka belajar,mereka sukses besar', 'C', '2', '223', 'Y', NULL, '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
(49, '3', '', 'Manakah yang bukan fungsi bahasa indonesiaâ€¦... ', NULL, 'alat pemersatu', 'ciri khas suatu bangsa', 'sebagai pembawa kewibawaan', 'gambar atau wacana', 'sebagai kerangka acuan', 'D', '2', '223', 'Y', NULL, '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
(50, '3', '', 'Bagi masyarakat Indonesia, bahasa indonesia resmi dipakai dalam deretan berikut, kecualiâ€¦â€¦', NULL, 'Bahasa pengajaran', 'bahasa iklan', 'bahasa sidang', 'bahasa resmi', 'bahasa undang-undang', 'B', '2', '223', 'Y', NULL, '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
(51, '3', '', 'dibandingkan informasi tulis, informasi lisan mempunyai kelebihan berupaâ€¦â€¦', NULL, 'situasi kebahasaan', 'pembicara', 'tema informasi', 'pendengar', 'sarana informasi', 'A', '2', '223', 'Y', NULL, '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
(52, '3', '', 'Ciri-ciri kalimat perintah terdapat dibawah ini kecualiâ€¦â€¦', NULL, 'ditandai oleh tanda seru', 'menggunakan kata kerja taktransitif', 'berisi perintah', 'menggunakan kata kerja transitif', 'biasanya menggunakan partikel lah', 'D', '2', '223', 'Y', NULL, '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
(53, '3', '', 'Manakah di antara deretan kalimat perintah berikut yang sopan?......', NULL, 'jangan suka menyakiti hati orang!', 'mari kita berangkat sekarang!', 'memang secepat itu kepergiannya!', 'berpikirlah,berbuat baiklah kau akan dapat sesuatu!', 'tolong kirimkan bingkisan ini kepada kekasihmu!', 'E', '2', '223', 'Y', NULL, '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
(54, '3', '', 'Untuk menanyakan alasan suatu kejadian digunakan kata tanya yang tepatâ€¦...', NULL, 'Apa', 'Mengapa', 'Kapan', 'Di mana', 'Siapa', 'B', '2', '223', 'Y', NULL, '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
