(1220, '31', '', 'Yang termasuk Ciri-ciri&nbsp;&nbsp;Official Assessmen System pada&nbsp;&nbsp;system&nbsp;&nbsp;pemungutan pajak adalah:&nbsp;', NULL, 'Wajib Pajak bersifat pasif', 'Wajib Pajak bersifat aktif.', 'Fiscus hanya mengawasi', 'Pajak ditentukan Wajib Pajak', 'Pajak ditentukan Pihak Ketiga', 'A', '4', '223', 'Y', NULL, '0000-00-00 00:00:00', '2016-12-15 02:11:10'),
(1221, '31', '', 'Alasan Negara memungut pajak&nbsp;&nbsp;menurut falsafah&nbsp;&nbsp;hukum&nbsp;&nbsp;yakni&nbsp;&nbsp;Negara berhak memungut pajak&nbsp;&nbsp;karena&nbsp;Negara melindungi keselamatan jiwa, harta benda dan hak-hak rakyatnya, oleh karena&nbsp;&nbsp;itu rakyat&nbsp;&nbsp;harus&nbsp;membayar&nbsp;&nbsp;pajak atas jaminan perlindungan tersebut hal&nbsp;&nbsp;ini&nbsp;&nbsp;termasuk teori ?', NULL, 'Teori Gaya Pikul     ', 'Teori Kepentingan&nbsp;&nbsp;', 'Teori Asuransi', 'Teori balas budi', 'Teori Asas daya beli.', 'C', '4', '223', 'Y', NULL, '0000-00-00 00:00:00', '2016-12-15 02:11:22'),
(1222, '31', '', 'Dalam pemungutan pajak, sebagai warga Negara yang berbakti, rakyat harus selalu menyadari bahwa pembayaran pajak adalah suatu kewajiban termasuk dalam teori ?', NULL, 'teori bakti', 'Teori Kepentingan&nbsp;&nbsp;', 'Teori Asuransi', 'Teori balas budi', 'Teori Asas daya beli.', 'A', '4', '223', 'Y', NULL, '0000-00-00 00:00:00', '2016-12-15 02:11:33'),
(1223, '31', '', 'Suatu system pemungutan pajak dimana perhitungan pemotongan dan&nbsp;&nbsp;pembayaran pajak serta pelaporan pajak dipercayakan kepada pihak ketiga oleh Negara, disebut system ?', NULL, 'Official Assesmen system&nbsp;&nbsp;&nbsp;', 'Withholding system', 'Multimatic system', '. Economic Official ', 'Rental Offcial ', 'B', '4', '223', 'Y', NULL, '0000-00-00 00:00:00', '2016-12-15 02:11:47'),
(1224, '31', '', 'Suatu system pemungutan pajak dimana aparatur pajak (fiskus) menetapkan&nbsp;&nbsp;jumlah&nbsp;&nbsp;pajak yang terutang dari wajib pajak, dalam&nbsp;&nbsp;system ini inisiatif dan kegiatan dalam menghitung dan&nbsp;&nbsp;menetapkan pajak sepenuhnya berada pada aparatur pajak (fiskus) system ini disebut ?', NULL, 'multimatic system', 'Withholding system    ', 'Official assessment system', 'Economic Official system', 'Rental Offcial system', 'C', '4', '223', 'Y', NULL, '0000-00-00 00:00:00', '2016-12-15 02:11:59'),
(1225, '31', '', 'Pengertian pajak adalah&nbsp;&nbsp;iuran kepada negara (yang dapat dipaksakan) yang terutang oleh yang&nbsp;&nbsp;wajib membayarnya menurut peraturan dengan tidak mendapat prestasi kembali yang langsung dapat ditunjuk dan gunanya untuk membiayai pengeluaran umum yang berhubungan dengan tugas Negara untuk penyelenggaraan pemerintahan, adalah pendapat tokoh :', NULL, 'Prof. Dr.&nbsp;Radius Prawiro&nbsp;', 'Prof. Dr. Rochmat Soemitro, SH', 'Prof. Dr. P.J.A. Andriani', 'Prof.Dr. Soemitro Joyohadikusumo', 'Prof.Dr. Awaluddin Jamin, SH.', 'C', '4', '223', 'Y', NULL, '0000-00-00 00:00:00', '2016-12-15 02:12:12'),
(1226, '31', '', 'Fungsi pajak disektor publik yakni merupakan alat atau sumber untuk memasukan uang dari masyarakat ke kas Negara yang disebut ?', NULL, 'Fungsi Controller&nbsp;&nbsp;', 'Fungsi Budgeter&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;', 'Fungsi Annualler', 'Fungsi Regulerend', 'Fungsi Financial', 'B', '4', '223', 'Y', NULL, '0000-00-00 00:00:00', '2016-12-15 02:12:24'),
(1227, '31', '', 'Fungsi pajak yang dipergunakan untuk mengatur atau mencapai tujuan tertentu dibidang ekonomi, politik, sosial, budaya, pertahanan dan keamanan seperti mengadakan perubahan tarif, memberikan pengecualian dan keringanan adalah fungsi ?', NULL, 'Fungsi Financial&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;', 'Fungsi Budgeter&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;', 'Fungsi Annualler', 'Fungsi Regulerend', 'Fungsi Controller', 'D', '4', '223', 'Y', NULL, '0000-00-00 00:00:00', '2016-12-15 02:12:35'),
