(1375, '32', '', 'Isi pokok QS. Al Baqarah ayat 148 adalah tentang...', NULL, 'Berbaik sangka', 'Bermusyawarah dalam kebaikan', 'Berkompetisi dalam Kebaikan', 'Berbudi pekerti luhur', 'Kerjasama', 'C', '2', '223', 'Y', NULL, '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
(1376, '32', '', 'Setiap amalan manusia akan dibalas Allah SWT. Meskipun sangat kecil, hal itu menunjukkan bahwa Allah SWt bersifat....', NULL, 'Maha Kuasa', 'maha Sempurna', 'Maha Penyayang', 'Maha Adil', 'Maha Pemurah', 'E', '2', '223', 'Y', NULL, '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
(1377, '32', '', 'Berikut yang tidak termasuk manfaat berkompetisi dalam kebaikan adalah...', NULL, 'Menumbuhkan sikap senang berbuat baik untuk memperoleh yang terbaik', 'Menghilangkan sikap Hasad dan iri hati dalam sesama', 'Melahirkan Ukhuwah Islamiyah, karena menganggap teman adalah kompetitor yang sehat', 'Mendorong orang untuk menghalalkan berbagai cara untuk mencapai hasil yang terbaik', 'Mendorong orang lain untuk berbuat yang lebih baik', 'D', '2', '223', 'Y', NULL, '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
(1378, '32', '', 'Manusia yang bersikap boros akan menjadi teman....', NULL, 'Jin', 'Qarun', 'Setan', 'Binatang', 'Ibnu Sabil', 'C', '2', '223', 'Y', NULL, '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
(1379, '32', '', 'Tanda-tanda orang berbuat baik kepada Allah SWT adalah sebagai berikut, kecuali...', NULL, 'Iman kepada Allah SWT', 'Memberikan harta yang dicintai kepada kerabat', 'Menolong kepada orang yang berbuat jahat', 'Mendirikan Shalat', 'Membayar zakat', 'C', '2', '223', 'Y', NULL, '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
(1380, '32', '', 'Seseorang hendaknya bersedekah ketika...', NULL, 'Kaya raya', 'Berkecukupan maupun kekurangan', 'Berkecukupan', 'Sedang mengalami kesulitan', 'Mampu memberi', 'B', '2', '223', 'Y', NULL, '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
(1381, '32', '', 'Dalam menyumbangkan pakaian untuk orang lain sebaiknya pakaian tersebut harus ...', NULL, 'Sudah tidak layak dipakai', 'Sudah bolong-bolong', 'Masih layak pakai', 'Yang paling jelek', 'Tidak bisa digunakan lagi', 'C', '2', '223', 'Y', NULL, '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
(1382, '32', '', 'Arti Rasul secara bahasa adalah...', NULL, 'Pembawa berita', 'Utusan', 'Sahabat', 'Terjaga', 'Pilihan', 'B', '2', '223', 'Y', NULL, '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
(1383, '32', '', 'Beriman kepada Rasul berarti...', NULL, 'memercayai dan menyakini dengan sepenuh hati bahwa Allah SWT telah memilih dan mengutus berapa orang pilihsn sebagai Rasul untuk menyampaikan wahyu', 'Percaya bahwa rasul adalah orang yang diberi mukjizat oleh Allah SWT untuk melaksanakan ajaranNya', 'Mengetahui bahwa rasul mampu menghindari umat manusia dari perbuatan keji dan munkar', 'percaya kepada kitab-kitab yang dibawa dan disebarluaskan oleh para rasul', 'Yakin bahwa jumlah seluruh nabi dan rasul adalah 25 orang', 'A', '2', '223', 'Y', NULL, '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
(1384, '32', '', 'Hamba Allah SWT yang diberikan wahyu dan harus disampaikan umatnya disebut...', NULL, 'Malaikat', ' Nabi', 'Rasul', 'Jibril', 'Jin', 'C', '2', '223', 'Y', NULL, '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
(1385, '32', '', 'Jumlah Rasul yang harus diketahui adalah....', NULL, '24', '34', '25', '22', '20', 'C', '2', '223', 'Y', NULL, '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
(1386, '32', '', 'Iman kepada rasul termasuk rukun iman yang ke...', NULL, '1', '2', '3', '4', '5', 'D', '2', '223', 'Y', NULL, '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
(1387, '32', '', 'Guna memperkuat risalahnya, seorang rasul dibekali...', NULL, 'Mukjizat', 'sihir', 'karamah', 'irhas', 'jimat', 'A', '2', '223', 'Y', NULL, '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
(1388, '32', '', 'Mustahil nabi dan rasul bersifat kizib, karena...', NULL, 'Jika bersikap kizib, ajaran nabi pasti adalah bohong dan tidak benar', 'Jika bersikap kizib, berartin nabi tidak menjalankan tugasnya dengan baik', 'Jika bersikap kizib, berarti nabi tidak bisa diajak berdialog', ' Jika bersikap kizib, nabi tidak bisa menyampaikan ajaranNya', 'Jika bersikap kizib, nabi justru akan menipu umatnya', 'A', '2', '223', 'Y', NULL, '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
(1389, '32', '', 'Apakah yang dimaksud dengan ulul azmi?', NULL, 'Para Nabi dan Rasul mempunyai kesabaran dan ketabahan yang luar biasa dalam tugasnya menyampaikan ajaran Allah SWT', 'nabi dan rasul yang dianggap memiliki kemampuan dialog dengan penentangnya', 'Nabi yang memperoleh wahyu tetapi tidak termasuk rasul yang menyampaikan ajran Allah SWT', 'Golongan orang-orang yang hidup dimasa Rasulullah SAW', 'Para khalifah zaman nabi Muhammad SAW', 'A', '2', '223', 'Y', NULL, '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
(1390, '32', '', 'Salah satu fungsi beriman kepada rasul adalah sebagai langkah pendalaman. Maksudnya adalah...', NULL, 'Sebagai perantara untuk memperoleh ajaran Allah SWT', 'Bisa mendalami ajaran agama melalui kerasulannya', 'Agar hati-hati dalam bertindak', 'Agar menjadi suri teladan', 'Meneladani rasulullah SAW', 'B', '2', '223', 'Y', NULL, '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
(1391, '32', '', '\"Allah SWT menyukai orang-orang yang bertobat\", terdapat dalam surat...', NULL, 'QS. Al Baqarah ayat 212', 'QS. Al Baqarah ayat 222', 'QS. Al Baqarah ayat 233', 'QS. Al Baqarah ayat 232', 'QS. Al Baqarah ayat 223', 'B', '2', '223', 'Y', NULL, '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
(1392, '32', '', 'Berikut ini yang termasuk contoh penerapan taubat nasuha adalah...', NULL, 'Hidupnya selalu menyesal', 'Selalu menyesali perbuatan yang salah', 'Selalu menyesali dosa-dosa dan meningkatkan amal shaleh', 'Selalu menyesali dosa-dosa dengan sesekali beramal shaleh', 'Selalu menyesali dosa-dosa menurut kemampuannya', 'C', '2', '223', 'Y', NULL, '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
(1393, '32', '', 'Salah satu manfaat taubat nasuha adalah', NULL, 'Hidup selalu diliputi ketakutan', 'Ibadahnya diterima oleh Allah SWT', 'Dihapuskan sebagian kesalahannya', 'Tidak dihormati orang lain', 'Hatinya selalu terenyuh', 'B', '2', '223', 'Y', NULL, '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
(1394, '32', '', 'Yang tidak termasuk sikap optimis adalah...', NULL, 'selalu menggali potensi diri', 'Selalu bersikap sabar', 'Berkata dan bertindak benar', 'Terus berusaha tanpa kenal lelah', 'Selalu bertindak cepat dan tergesa-gesa', 'E', '2', '223', 'Y', NULL, '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
(1395, '32', '', 'Pernyataan dibawah ini adalah hikmah dari sikap optimis, kecuai...', NULL, 'Hidup lebih tertata dan terarah', 'Diampuni semua dosa-dosanya', 'Giat bekerja tanpa kenal lelah', 'Selalu berpikir positif atas segala kejadian', 'Tidak mudah putus asa', 'B', '2', '223', 'Y', NULL, '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
(1396, '32', '', 'Sikap yang harus dilakukan setelah berusaha adalah...', NULL, 'Tawakkal', 'Pantang Menyerah', 'Ikhtiar', 'Putus asa', 'Menata target', 'A', '2', '223', 'Y', NULL, '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
(1397, '32', '', 'QS. Al Baqarah ayat 275 menjelaskan bahwa ...', NULL, 'Pekerjaan yang paling baik adalah jual beli dengan cara bersih', 'Allah SWT mengharamkan jual beli khamar (arak)', 'Allah SWT menghalalkan jual beli dan mengharamkan riba', 'barang pinjaman harus dikembalikan', 'orang-orang yang boros adalah saudara syetan', 'C', '2', '223', 'Y', NULL, '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
(1398, '32', '', 'Jual beli harus didasari dengan...', NULL, 'Kebohongan', 'Saling rela', 'penipuan', 'Kecurangan', 'perusakan', 'B', '2', '223', 'Y', NULL, '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
(1399, '32', '', 'Rukun jual beli terdiri atas...', NULL, '3 macam', '5 macam', '6 macam', '4 macam', '7 macam', 'B', '2', '223', 'Y', NULL, '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
