(1511, '34', '', 'Ajaran Tuhan Yesus yang ekstrim dalam menghadapi orang yang menampar kita adalahâ€¦â€¦', NULL, 'berikan pipi yang satunya lagi untuk ditampar', 'membalas dengan tamparan agar lawan merasakan hal yang sama', 'menjauhi dan memusuhi orang yang menampar kita', 'mendoakan orang tersebut agar dihukum Tuhan', 'menutup diri dan tidak bergaul dengan orang yang menampar kita tersebut', 'A', '2', '223', 'Y', NULL, '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
(1512, '34', '', 'Ringkasan ajaran Yesus tentang sesama adalahâ€¦â€¦', NULL, 'kasihilah musuhmu', 'kasihilah Tuhan Allahmu dengan segenap hatimu', 'kasihilah sesamamu manusia seperti dirimu sendiri', 'hormatilah ayah dan ibumu supaya panjang umurmu', 'barangsiapa mempunyai dua helai baju,berikanlah yang sehelai kepada sesamamu', 'C', '2', '223', 'Y', NULL, '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
