(1521, '34', '', 'Yang merasa hidupnya paling bermoral daripada sesamanya adalahâ€¦â€¦', NULL, 'ahli-ahli taurat', 'perempuann kanaan', 'bangsa israel', 'harun', 'yosua', 'A', '2', '223', 'Y', NULL, '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
