(1529, '34', '', '\"Jangan menyebut nama Tuhan Allah dengan sembarangan karena Allah akan menghukum orang yang menyalahgunakan nama-Nya\" tertulis dalam hukum taurat yangâ€¦... ', NULL, 'pertama', 'kedua', 'ketiga', 'keempat', 'kelima', 'C', '2', '223', 'Y', NULL, '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
(1530, '34', '', 'mendahulukan logika daripada perasaan memikirkan masa depan yang lebih baik hal buruk dengan tenang dan stabi, adalah beberapa ciri pertumbuhan orang dewasa dalam aspekâ€¦â€¦', NULL, 'intelektual', 'emosi ', 'moral', 'spritual', 'sosial', 'A', '2', '223', 'Y', NULL, '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
