(1532, '34', '', 'Perkara yang rumit tetapi dapat dikendalikan dan dimanfaatkan untuk hal-hal yang jauh lebih baik. Ini adalah salah satu defenisi dari aspekâ€¦â€¦', NULL, 'sosial', 'spritual', 'emosi', 'moral', 'emosi', 'E', '2', '223', 'Y', NULL, '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
