(1534, '34', '', 'Sebuah tindakan dikatan salah apabila mendapatkan hukuman atau sanksi,sedangkan tindakan yang mendapatkan pahala dianggap tindakan yang benar ini adalah salah satu tahap dalam aspek....', NULL, 'fisik', 'emosi', 'spritual', 'intelektual', 'moral', 'E', '2', '223', 'Y', NULL, '0000-00-00 00:00:00', '0000-00-00 00:00:00'),
