INSERT INTO `materis` (`id`, `id_user`, `judul`, `isi`, `gambar`, `status`, `hits`, `sesi`, `created_at`, `updated_at`) VALUES
(1, 1, 'Belajar AJAX yukkk...', '<p style=\"margin-bottom: 1em; padding: 0px; border: 0px; clear: both;\" helvetica=\"\" neue\",=\"\" helvetica,=\"\" sans-serif;\"=\"\">There are several possibilities...</p><p style=\"margin-top: 0px; margin-bottom: 1em; padding: 0px; border: 0px; font-size: 15px; clear: both; color: rgb(36, 39, 41); font-family: Arial, \" helvetica=\"\" neue\",=\"\" helvetica,=\"\" sans-serif;\"=\"\">1) If you have any spaces at all in front of your opening&nbsp;<code style=\"margin: 0px; padding: 1px 5px; border: 0px; font-size: 13px; font-family: Consolas, Menlo, Monaco, \" lucida=\"\" console\",=\"\" \"liberation=\"\" mono\",=\"\" \"dejavu=\"\" sans=\"\" \"bitstream=\"\" vera=\"\" \"courier=\"\" new\",=\"\" monospace,=\"\" sans-serif;=\"\" background-color:=\"\" rgb(239,=\"\" 240,=\"\" 241);=\"\" white-space:=\"\" pre-wrap;\"=\"\"><!--?php</code-->&nbsp;tag, it can cause this error (especially if you\'re using AJAX). So just double-check to make sure that there\'s nothing before&nbsp;<code style=\"margin: 0px; padding: 1px 5px; border: 0px; font-size: 13px; font-family: Consolas, Menlo, Monaco, \" lucida=\"\" console\",=\"\" \"liberation=\"\" mono\",=\"\" \"dejavu=\"\" sans=\"\" \"bitstream=\"\" vera=\"\" \"courier=\"\" new\",=\"\" monospace,=\"\" sans-serif;=\"\" background-color:=\"\" rgb(239,=\"\" 240,=\"\" 241);=\"\" white-space:=\"\" pre-wrap;\"=\"\"><!--?php</code-->&nbsp;in your files.</code></code></p><p style=\"margin-top: 0px; margin-bottom: 1em; padding: 0px; border: 0px; font-size: 15px; clear: both; color: rgb(36, 39, 41); font-family: Arial, \" helvetica=\"\" neue\",=\"\" helvetica,=\"\" sans-serif;\"=\"\"><code style=\"margin: 0px; padding: 1px 5px; border: 0px; font-size: 13px; font-family: Consolas, Menlo, Monaco, \" lucida=\"\" console\",=\"\" \"liberation=\"\" mono\",=\"\" \"dejavu=\"\" sans=\"\" \"bitstream=\"\" vera=\"\" \"courier=\"\" new\",=\"\" monospace,=\"\" sans-serif;=\"\" background-color:=\"\" rgb(239,=\"\" 240,=\"\" 241);=\"\" white-space:=\"\" pre-wrap;\"=\"\"><code style=\"margin: 0px; padding: 1px 5px; border: 0px; font-size: 13px; font-family: Consolas, Menlo, Monaco, \" lucida=\"\" console\",=\"\" \"liberation=\"\" mono\",=\"\" \"dejavu=\"\" sans=\"\" \"bitstream=\"\" vera=\"\" \"courier=\"\" new\",=\"\" monospace,=\"\" sans-serif;=\"\" background-color:=\"\" rgb(239,=\"\" 240,=\"\" 241);=\"\" white-space:=\"\" pre-wrap;\"=\"\">2) If you\'re trying to submit this form data via AJAX, the docs suggest passing the CSRF token like so:</code></code></p><p style=\"margin-top: 0px; margin-bottom: 1em; padding: 0px; border: 0px; font-size: 15px; clear: both; color: rgb(36, 39, 41); font-family: Arial, \" helvetica=\"\" neue\",=\"\" helvetica,=\"\" sans-serif;\"=\"\"><code style=\"margin: 0px; padding: 1px 5px; border: 0px; font-size: 13px; font-family: Consolas, Menlo, Monaco, \" lucida=\"\" console\",=\"\" \"liberation=\"\" mono\",=\"\" \"dejavu=\"\" sans=\"\" \"bitstream=\"\" vera=\"\" \"courier=\"\" new\",=\"\" monospace,=\"\" sans-serif;=\"\" background-color:=\"\" rgb(239,=\"\" 240,=\"\" 241);=\"\" white-space:=\"\" pre-wrap;\"=\"\"><code style=\"margin: 0px; padding: 1px 5px; border: 0px; font-size: 13px; font-family: Consolas, Menlo, Monaco, \" lucida=\"\" console\",=\"\" \"liberation=\"\" mono\",=\"\" \"dejavu=\"\" sans=\"\" \"bitstream=\"\" vera=\"\" \"courier=\"\" new\",=\"\" monospace,=\"\" sans-serif;=\"\" background-color:=\"\" rgb(239,=\"\" 240,=\"\" 241);=\"\" white-space:=\"\" pre-wrap;\"=\"\">Add this meta tag to your&nbsp;<code style=\"margin: 0px; padding: 1px 5px; border: 0px; font-size: 13px; font-family: Consolas, Menlo, Monaco, \" lucida=\"\" console\",=\"\" \"liberation=\"\" mono\",=\"\" \"dejavu=\"\" sans=\"\" \"bitstream=\"\" vera=\"\" \"courier=\"\" new\",=\"\" monospace,=\"\" sans-serif;=\"\" background-color:=\"\" rgb(239,=\"\" 240,=\"\" 241);=\"\" white-space:=\"\" pre-wrap;\"=\"\"></code>:</code></code></p><pre class=\"lang-php prettyprint prettyprinted\" style=\"margin-bottom: 1em; padding: 5px; border-width: 0px; border-style: initial; border-color: initial; font-size: 13px; width: auto; max-height: 600px; font-family: Consolas, Menlo, Monaco, \" lucida=\"\" console\",=\"\" \"liberation=\"\" mono\",=\"\" \"dejavu=\"\" sans=\"\" \"bitstream=\"\" vera=\"\" \"courier=\"\" new\",=\"\" monospace,=\"\" sans-serif;=\"\" background-color:=\"\" rgb(239,=\"\" 240,=\"\" 241);=\"\" color:=\"\" rgb(57,=\"\" 51,=\"\" 24);=\"\" word-wrap:=\"\" normal;\"=\"\"><code style=\"margin: 0px; padding: 1px 5px; border: 0px; font-size: 13px; font-family: Consolas, Menlo, Monaco, \" lucida=\"\" console\",=\"\" \"liberation=\"\" mono\",=\"\" \"dejavu=\"\" sans=\"\" \"bitstream=\"\" vera=\"\" \"courier=\"\" new\",=\"\" monospace,=\"\" sans-serif;=\"\" background-color:=\"\" rgb(239,=\"\" 240,=\"\" 241);=\"\" white-space:=\"\" pre-wrap;\"=\"\"><code style=\"margin: 0px; padding: 1px 5px; border: 0px; font-size: 13px; font-family: Consolas, Menlo, Monaco, \" lucida=\"\" console\",=\"\" \"liberation=\"\" mono\",=\"\" \"dejavu=\"\" sans=\"\" \"bitstream=\"\" vera=\"\" \"courier=\"\" new\",=\"\" monospace,=\"\" sans-serif;=\"\" background-color:=\"\" rgb(239,=\"\" 240,=\"\" 241);=\"\" white-space:=\"\" pre-wrap;\"=\"\"><code style=\"margin: 0px; border: 0px; font-size: 13px; font-family: Consolas, Menlo, Monaco, \" lucida=\"\" console\",=\"\" \"liberation=\"\" mono\",=\"\" \"dejavu=\"\" sans=\"\" \"bitstream=\"\" vera=\"\" \"courier=\"\" new\",=\"\" monospace,=\"\" sans-serif;=\"\" background-color:=\"\" rgb(239,=\"\" 240,=\"\" 241);=\"\" white-space:=\"\" inherit;\"=\"\"><span class=\"tag\" style=\"margin: 0px; padding: 0px; border: 0px; color: rgb(125, 39, 39);\"><meta< span=\"\"><span class=\"pln\" style=\"margin: 0px; padding: 0px; border: 0px; color: rgb(48, 51, 54);\"> </span><span class=\"atn\" style=\"margin: 0px; padding: 0px; border: 0px; color: rgb(230, 67, 32);\">name</span><span class=\"pun\" style=\"margin: 0px; padding: 0px;